-- Administrator-run functional checks. Every fixture is rolled back.
begin;
do $$
declare
 owner_a uuid=gen_random_uuid(); outsider uuid=gen_random_uuid(); munshi uuid=gen_random_uuid();
 wid uuid; sid uuid; tank uuid; nozzle uuid; account uuid; vehicle uuid; token uuid; shift uuid;
 capture uuid=gen_random_uuid(); capture2 uuid=gen_random_uuid(); eid uuid; eid2 uuid; request_id uuid=gen_random_uuid();
 file_path text; result jsonb; saved jsonb; payload jsonb; fill jsonb; context jsonb; failed boolean;
begin
 insert into auth.users(id,email,email_confirmed_at,aud,role) values(owner_a,owner_a||'@example.invalid',now(),'authenticated','authenticated'),(outsider,outsider||'@example.invalid',now(),'authenticated','authenticated'),(munshi,munshi||'@example.invalid',now(),'authenticated','authenticated');
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 execute 'set local role authenticated';
 wid=(public.command('join','{"name":"Offline QA","person":"QA owner"}')->>'id')::uuid;
 sid=(public.command('station','{"name":"Field QA station","omc":"QA","city":"Karachi"}')->>'id')::uuid;
 tank=(public.command('tank',jsonb_build_object('station_id',sid,'name','Petrol','grade','MS','capacity',50000,'dip',2000,'chart','[{"mm":0,"liters":0},{"mm":5000,"liters":50000}]'::jsonb))->>'id')::uuid;
 nozzle=(public.command('nozzle',jsonb_build_object('station_id',sid,'tank_id',tank,'name','N1','totalizer',1000))->>'id')::uuid;
 perform public.command('price',jsonb_build_object('station_id',sid,'grade','MS','price',300,'beta',0.00115,'margin',10,'effective_at',now(),'source','QA fixture'));
 account=(public.command('account',jsonb_build_object('station_id',sid,'name','QA fleet','credit_limit',50000))->>'id')::uuid;
 vehicle=(public.command('vehicle',jsonb_build_object('station_id',sid,'account_id',account,'registration','FIELD-QA','grade','MS','max_liters',200))->>'id')::uuid;
 select v.token into token from public.vehicles v where v.id=vehicle;
 perform public.command('invite',jsonb_build_object('station_id',sid,'email',munshi||'@example.invalid','name','Field Munshi'));
 shift=(public.command('open_shift',jsonb_build_object('station_id',sid,'name','Field QA shift'))->>'id')::uuid;
 perform public.field('station_position',jsonb_build_object('station_id',sid,'latitude',24.86,'longitude',67.03,'radius_m',500));
 assert (select latitude from public.stations where id=sid)=24.86,'Station pin was not saved';
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 perform public.command('join','{"name":"Outsider QA"}');
 failed=false;begin perform public.field('context',jsonb_build_object('station_id',sid));exception when others then failed=true;end;assert failed,'Cross-workspace field context allowed';
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 perform public.command('join','{}');
 context=public.field('context',jsonb_build_object('station_id',sid));
 assert context->'shift'->>'id'=shift::text,'Wrong saved shift';
 assert not(context ? 'prices') and not(context ? 'accounts') and not(context->'tanks'->0 ? 'stock') and not(context->'tanks'->0 ? 'chart'),'Offline context disclosed finances';
 assert public.field('vehicle_lookup',jsonb_build_object('station_id',sid,'token',token))->>'registration'='FIELD-QA','Issued pass lookup failed';
 failed=false;begin perform public.field('station_position',jsonb_build_object('station_id',sid,'latitude',0,'longitude',0));exception when others then failed=true;end;assert failed,'Munshi changed station pin';
 file_path=wid||'/'||munshi||'/'||capture||'.jpg';
 execute 'reset role';
 insert into storage.objects(bucket_id,name,owner_id) values('evidence',file_path,munshi::text),('evidence',wid||'/'||munshi||'/'||capture2||'.jpg',munshi::text);
 execute 'set local role authenticated';
 payload=jsonb_build_object('station_id',sid,'capture_id',capture,'path',file_path,'sha256',repeat('a',64),'captured_at',now(),'latitude',24.86,'longitude',67.03,'accuracy',10);
 eid=(public.field('offline_evidence',payload)->>'id')::uuid;
 assert (public.field('offline_evidence',payload)->>'id')::uuid=eid,'Evidence retry duplicated photo';
 failed=false;begin perform public.field('offline_evidence',payload||jsonb_build_object('sha256',repeat('b',64)));exception when others then failed=true;end;assert failed,'Changed capture identity accepted';
 failed=false;begin perform public.field('offline_evidence',payload||jsonb_build_object('capture_id',capture2,'path',wid||'/'||munshi||'/'||capture2||'.jpg','captured_at',now()-interval '25 hours'));exception when others then failed=true;end;assert failed,'Old offline photo accepted';
 eid2=(public.field('offline_evidence',payload||jsonb_build_object('capture_id',capture2,'path',wid||'/'||munshi||'/'||capture2||'.jpg'))->>'id')::uuid;
 fill=jsonb_build_object('token',token,'nozzle_id',nozzle,'liters',100,'evidence_id',eid);
 payload=jsonb_build_object('station_id',sid,'user_id',munshi,'workspace_id',wid,'shift_id',shift,'request_id',request_id,'kind','parchi','captured_at',now(),'payload',fill);
 saved=public.field('sync',payload);
 result=public.field('sync',payload);
 assert result->>'id'=saved->>'id' and result->>'replayed'='true','Replay was not idempotent';
 failed=false;begin perform public.field('sync',payload||jsonb_build_object('payload',fill||'{"liters":101}'::jsonb));exception when others then failed=true;end;assert failed,'Changed replay payload accepted';
 failed=false;begin perform public.field('sync',payload||jsonb_build_object('request_id',gen_random_uuid(),'payload',fill||jsonb_build_object('evidence_id',eid2)));exception when others then failed=true;end;assert failed,'Offline posting bypassed credit limit';
 failed=false;begin perform public.field('sync',payload||jsonb_build_object('request_id',gen_random_uuid(),'payload',fill||'{"liters":1}'::jsonb));exception when others then failed=true;end;assert failed,'Offline photo reused';
 execute 'reset role';
 assert (select balance from public.accounts where id=account)=30000,'Retry double-posted credit';
 assert (select offline_request_id from public.parchis where id=(saved->>'id')::uuid)=request_id,'Offline provenance missing';
 update public.shifts set status='review' where id=shift;
 execute 'set local role authenticated';
 assert public.field('sync',payload)->>'id'=saved->>'id','Lost-response retry failed after shift closure';
 assert public.command('parchi',fill||jsonb_build_object('station_id',sid,'request_id',request_id))->>'id'=saved->>'id','Online retry failed after closure';
 failed=false;begin perform public.field('sync',payload||jsonb_build_object('request_id',gen_random_uuid(),'payload',fill||jsonb_build_object('evidence_id',eid2,'liters',1)));exception when others then failed=true;end;assert failed,'Closed original shift accepted a new offline fill';
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 perform public.command('revoke',jsonb_build_object('id',munshi));
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 failed=false;begin perform public.field('sync',payload);exception when others then failed=true;end;assert failed,'Revoked access replay accepted';
 execute 'set local role anon';
 failed=false;begin perform public.field('context',jsonb_build_object('station_id',sid));exception when others then failed=true;end;assert failed,'Anonymous field RPC allowed';
 execute 'reset role';
end $$;
select 'PASS: offline idempotency, changed replay, original shift, credit, evidence, tenant/role boundaries and revocation; fixtures rolled back' as result;
rollback;
